import heapq


def _interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        if mandatory & blocked:
            return {"error": "impossible"}
        options = [job for job in jobs if job["id"] not in blocked]
        if len(mandatory) > k or len(options) < k:
            return {"error": "impossible"}
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None
        for choice in combinations(options, k):
            ids = tuple(sorted(job["id"] for job in choice))
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in choice:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            events = []
            for job in choice:
                events.append((job["start"], 1))
                events.append((job["end"], -1))
            active = 0
            valid = True
            for _, delta in sorted(events):  # ends (-1) precede starts (+1)
                active += delta
                if active > capacity:
                    valid = False
                    break
            if not valid:
                continue
            value = sum(job["value"] for job in choice)
            better_tie = (best_ids is None or
                          (ids > best_ids if tie == "largest" else ids < best_ids))
            if best_value is None or value > best_value or (value == best_value and better_tie):
                best_value, best_ids = value, ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _component_06(data):
    def rounded(num, den, mode):
        q, r = divmod(num, den)
        return q + (1 if mode == "half_up" and 2 * r >= den else 0)

    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (seq, event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000, mode)
        tax = rounded(raw * event.get("tax_bp", 0), 10000, mode)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _component_07(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    choices = []
    for name in names:
        choices.append([None] + [row for row in packages[name]
                                  if row["version"] not in blocked.get(name, [])])

    best_score = None
    best_versions = None
    for selection in product(*choices):
        installed = {name: row for name, row in zip(names, selection) if row is not None}
        valid = True
        for name, (low, high) in roots.items():
            row = installed.get(name)
            if row is None or not low <= row["version"] <= high:
                valid = False
                break
        if not valid:
            continue
        if any(name in installed and installed[name]["version"] != version
               for name, version in pins.items()):
            continue

        edges = {name: [] for name in installed}
        for name, row in installed.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = installed.get(dep["name"])
                if target is None or not dep["min"] <= target["version"] <= dep["max"]:
                    valid = False
                    break
                edges[name].append(dep["name"])
            if not valid:
                break
        if not valid:
            continue

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for dep_name in edges[name]:
                if not visit(dep_name):
                    return False
            state[name] = 2
            return True

        if any(not visit(name) for name in installed):
            continue
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges[name])
        if reachable != set(installed):
            continue

        score = tuple(installed[name]["version"] if name in installed else -1
                      for name in reversed(names))
        if best_score is None or score > best_score:
            best_score = score
            best_versions = {name: row["version"] for name, row in installed.items()}
    if best_score is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _component_08(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit.get(source, 0)
    start_state = (source, initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            next_mask = mask | bit.get(edge["v"], 0)
            for duration, next_remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, edge["v"], next_mask, next_remaining))
    return {"arrival": None}


